-- nodereact seeder: ALL data from the dump (8 tables with data; billing, deleted_drivers,
-- online_users, user_stats are empty in the dump).
-- Re-runnable: rows are inserted, or UPDATED to the dump values if the id already exists.
-- Nothing is deleted. Requires the tables to exist (see nodereact_schema.sql).
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';

-- groups
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `description`=VALUES(`description`), `color`=VALUES(`color`);

-- users
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `email`=VALUES(`email`), `password`=VALUES(`password`), `role`=VALUES(`role`), `created_at`=VALUES(`created_at`), `last_login`=VALUES(`last_login`);

-- drivers
ON DUPLICATE KEY UPDATE `unit`=VALUES(`unit`), `name`=VALUES(`name`), `dimensions`=VALUES(`dimensions`), `payload`=VALUES(`payload`), `license_plate`=VALUES(`license_plate`), `phone`=VALUES(`phone`), `location`=VALUES(`location`), `zip`=VALUES(`zip`), `latitude`=VALUES(`latitude`), `longitude`=VALUES(`longitude`), `emergency`=VALUES(`emergency`), `date`=VALUES(`date`), `insurance_date`=VALUES(`insurance_date`), `ins_exp`=VALUES(`ins_exp`), `registration_date`=VALUES(`registration_date`), `reg_exp`=VALUES(`reg_exp`), `comments`=VALUES(`comments`), `email`=VALUES(`email`), `available`=VALUES(`available`), `onload`=VALUES(`onload`), `reserved_at`=VALUES(`reserved_at`), `reserved_by`=VALUES(`reserved_by`), `created_at`=VALUES(`created_at`), `updated_at`=VALUES(`updated_at`);

-- driver_groups

-- user_groups

-- audit_logs
ON DUPLICATE KEY UPDATE `user_id`=VALUES(`user_id`), `action`=VALUES(`action`), `object_type`=VALUES(`object_type`), `object_id`=VALUES(`object_id`), `ip_address`=VALUES(`ip_address`), `device_info`=VALUES(`device_info`), `details`=VALUES(`details`), `created_at`=VALUES(`created_at`);

-- refresh_tokens
ON DUPLICATE KEY UPDATE `user_id`=VALUES(`user_id`), `token`=VALUES(`token`), `device_info`=VALUES(`device_info`), `ip_address`=VALUES(`ip_address`), `expires_at`=VALUES(`expires_at`), `created_at`=VALUES(`created_at`), `revoked_at`=VALUES(`revoked_at`), `rotation_reason`=VALUES(`rotation_reason`);

-- user_sessions
ON DUPLICATE KEY UPDATE `user_id`=VALUES(`user_id`), `socket_id`=VALUES(`socket_id`), `connected_at`=VALUES(`connected_at`), `disconnected_at`=VALUES(`disconnected_at`), `duration_seconds`=VALUES(`duration_seconds`);

SET FOREIGN_KEY_CHECKS=1;
